(()=>{
function itemCount(id){const value=document.getElementById(id)?.textContent||'';return Number(value.match(/(?:^|·)\s*(\d+)\s*项/)?.[1]||0)}
function updateConfirmation(){const panel=document.querySelector('#confirmations'),bar=document.querySelector('.confirmation-taskbar');if(!panel||!bar)return;const pending=itemCount('confirmation-count'),problems=itemCount('data-error-count');bar.querySelector('[data-pending-number]').textContent=pending;bar.querySelector('[data-problem-number]').textContent=problems;const jump=bar.querySelector('.taskbar-jump');jump.disabled=pending===0;jump.textContent=pending?'查看待确认':'暂无待确认';panel.classList.toggle('has-confirmations',pending>0)}
function emphasize(){const tab=document.querySelector('#data-tab'),panel=document.querySelector('#confirmations');if(!tab||!panel)return;if(!tab.querySelector('.confirmation-taskbar')){const bar=document.createElement('div');bar.className='confirmation-taskbar';bar.innerHTML='<div class="taskbar-copy"><span class="taskbar-title"><strong data-pending-number>0</strong>项待人工确认</span><span class="taskbar-secondary">另有 <span data-problem-number>0</span> 项数据问题，见下方明细</span></div><button type="button" class="taskbar-jump" aria-controls="confirmations">查看待确认</button>';tab.prepend(bar);bar.querySelector('button').addEventListener('click',()=>{panel.tabIndex=-1;panel.focus({preventScroll:true});panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})})}panel.querySelectorAll('tbody tr:not(.data-group-header)').forEach(row=>{row.cells[1]?.classList.add('decision-proposal')});updateConfirmation()}
const previousRender=render;render=function(){previousRender();emphasize()};const previousFilters=applyFilters;applyFilters=function(){previousFilters();updateConfirmation()};emphasize();
})();
